package com.smartspend;
import org.springframework.stereotype.Service;import java.math.*;import java.time.*;import java.util.*;
@Service class AuditService{final AuditRepo repo;AuditService(AuditRepo r){repo=r;}void record(User user,String action,String description){AuditLog x=new AuditLog();x.user=user;x.action=action;x.description=description;x.ipAddress="local";repo.save(x);}}
@Service class NotificationService{final NotificationRepo repo;final ExpenseRepo expenses;final IncomeRepo incomes;final BudgetRepo budgets;NotificationService(NotificationRepo r,ExpenseRepo e,IncomeRepo i,BudgetRepo b){repo=r;expenses=e;incomes=i;budgets=b;}void notify(User user,String type,String message){boolean exists=repo.findByUserIdOrderByCreatedAtDesc(user.id).stream().anyMatch(n->type.equals(n.type)&&message.equals(n.message)&&n.createdAt.toLocalDate().equals(LocalDate.now()));if(!exists){Notification n=new Notification();n.user=user;n.type=type;n.message=message;repo.save(n);}}void evaluate(User user){LocalDate today=LocalDate.now(),monthStart=today.withDayOfMonth(1),previousStart=monthStart.minusMonths(1);var currentExpenses=expenses.findByUserIdAndDateBetween(user.id,monthStart,today);BigDecimal total=currentExpenses.stream().map(Expense::getAmount).reduce(BigDecimal.ZERO,BigDecimal::add);Map<String,BigDecimal> categories=new HashMap<>();currentExpenses.forEach(e->categories.merge(e.category.name,e.amount,BigDecimal::add));categories.forEach((name,amount)->{if(FinancialRules.highCategorySpending(amount,total))notify(user,"HIGH_CATEGORY_SPENDING","High spending detected in "+name+" for "+today.getYear()+"-"+String.format("%02d",today.getMonthValue())+".");});LocalDate previousEnd=previousStart.plusDays(Math.min(today.getDayOfMonth()-1,previousStart.lengthOfMonth()-1));BigDecimal previous=expenses.findByUserIdAndDateBetween(user.id,previousStart,previousEnd).stream().map(Expense::getAmount).reduce(BigDecimal.ZERO,BigDecimal::add);if(FinancialRules.spendingIncreased(total,previous))notify(user,"SPENDING_INCREASE","Spending increased compared with previous month.");BigDecimal income=incomes.findByUserIdAndDateBetween(user.id,monthStart,today).stream().map(Income::getAmount).reduce(BigDecimal.ZERO,BigDecimal::add);if(FinancialRules.lowSavings(income,total))notify(user,"LOW_SAVINGS","Consider reducing non-essential expenses.");budgets.findByUserId(user.id).forEach(b->{LocalDate from=LocalDate.of(b.year,b.month,1),to=from.plusMonths(1).minusDays(1);BigDecimal used=expenses.findByUserIdAndDateBetween(user.id,from,to).stream().filter(e->b.category==null||e.category.id.equals(b.category.id)).map(Expense::getAmount).reduce(BigDecimal.ZERO,BigDecimal::add);String status=FinancialRules.budgetStatus(used,b.amount);String scope=b.category==null?"Overall budget":"Budget for "+b.category.name;if("EXCEEDED".equals(status))notify(user,"BUDGET_EXCEEDED",scope+" exceeded for "+b.month+"/"+b.year+".");else if("WARNING".equals(status))notify(user,"BUDGET_WARNING",scope+" is approaching its limit for "+b.month+"/"+b.year+".");});}}
